import json
import os

H = "/Users/gabe/.claude/jobs/45cd44b5/tmp/harvest"
for d in ["trails", "changes", "findings", "approvals", "sessions", "transcripts"]:
    n = size = errs = 0
    for root, _, files in os.walk(f"{H}/{d}"):
        for f in files:
            p = os.path.join(root, f)
            n += 1
            size += os.path.getsize(p)
            with open(p, errors="replace") as fh:
                if fh.read(6) == "ERROR ":
                    errs += 1
    print(f"{d}: files={n} bytes={size} errors={errs}")

for repo in ["caliper", "callisto"]:
    tot = {}
    fr = f"{H}/findings/{repo}"
    nfind = nonempty = 0
    for f in sorted(os.listdir(fr)) if os.path.isdir(fr) else []:
        t = open(os.path.join(fr, f)).read()
        if t.startswith("ERROR"):
            continue
        d = json.loads(t)
        nfind += len(d.get("findings", []))
        if d.get("findings"):
            nonempty += 1
        for k, v in d.get("counts", {}).items():
            tot[k] = tot.get(k, 0) + v
        if d.get("has_more"):
            print("has_more:", f)
    print(repo, "findings:", nfind, "changes with findings:", nonempty, tot)

idx = {}
for repo in ["caliper", "callisto"]:
    try:
        s = json.load(open(f"{H}/sessions/{repo}-index.json"))
        print(repo, "sessions indexed:", len(s))
    except Exception as e:
        print(repo, "no session index", e)
print(open(f"{H}/harvest.log").read().splitlines()[-1])

