import glob
import os
import re

R = "/Users/gabe/Projects/wisp-plugins/.claude/worktrees/review-slop-evaluation"
os.chdir(R)


def rd(p):
    return open(p, errors="replace").read()


def real(p):
    return not re.search(r"^plugins/[^/]+/(shared|subagents)/", p)


SKIP = ("CHANGELOG.md", "docs/evaluations", "dist/", "shared/schemas/")
ALL = [p for p in glob.glob("**/*", recursive=True)
       if os.path.isfile(p) and real(p) and not any(s in p for s in SKIP)
       and not p.startswith(("node_modules", ".claude/worktrees", "pnpm-lock"))]


def hits(pat, paths=ALL):
    r = re.compile(pat)
    out = []
    for p in paths:
        try:
            for i, line in enumerate(rd(p).splitlines(), 1):
                if r.search(line):
                    out.append(f"{p}:{i}")
        except Exception:
            pass
    return out


print("files scanned", len(ALL))
print("5. arch-spec@1:", hits(r"arch-spec@1"))
print("6. hook scripts referenced (non-self):",
      [h for h in hits(r"pre-command\.sh|subagent-start\.sh") if not h.startswith("shared/hooks/")])
