print("   spec_file_path agents:", sorted({h.split(':')[0] for h in hits(r"spec_file_path", [p for p in agents_skills if '/agents/' in p])}))
print("--- navigator SKILL estimator lines")
for i, l in enumerate(rd("plugins/navigator/skills/plan/SKILL.md").splitlines(), 1):
    if "estimator" in l.lower() or "estimate" in l.lower():
        print(f"   {i}: {l.strip()[:220]}")
print("--- navigator plugin.json estimator line")
for i, l in enumerate(rd("plugins/navigator/plugin.json").splitlines(), 1):
    if "estimator" in l:
        print(f"   {i}: {l.strip()}")
print("--- muse exit-gate lines 36-41")
for i, l in enumerate(rd("plugins/muse/agents/exit-gate.md").splitlines()[35:41], 36):
    print(f"   {i}: {l.strip()[:200]}")
print("--- vanguard research SKILL 17-21")
for i, l in enumerate(rd("plugins/vanguard/skills/research/SKILL.md").splitlines()[16:21], 17):
    print(f"   {i}: {l.strip()[:220]}")

