import glob
import json
import re

sid = "6cc3e47b-8406-4c17-94fb-22313682fad8"
paths = glob.glob(f"/Users/gabe/.claude/projects/*/{sid}.jsonl")
print("paths", paths)
if not paths:
    raise SystemExit
turns = []
for line in open(paths[0], errors="replace"):
    try:
        o = json.loads(line)
    except Exception:
        continue
    m = o.get("message") or {}
    role = m.get("role") or o.get("type")
    c = m.get("content")
    if isinstance(c, list):
        txt = " ".join(b.get("text", "") for b in c if isinstance(b, dict) and b.get("type") == "text")
    else:
        txt = c if isinstance(c, str) else ""
    if txt and role in ("user", "assistant"):
        turns.append((role, o.get("timestamp", ""), txt))
print("turns", len(turns), "user", sum(1 for r, _, _ in turns if r == "user"))
kw = re.compile(r"finding|Entire|trail|reproduc|sibling|race|concurren|stale|refute|worker|agent", re.I)
for i, (r, ts, t) in enumerate(turns):
    if r == "user" and not t.startswith(("<system", "<command", "Caveat")):
        print(f"\n#{i} USER {ts[11:19]}: {t[:500]!r}")
    elif r == "assistant" and kw.search(t) and len(t) > 120:
        print(f"#{i} ASSISTANT {ts[11:19]}: {t[:420]!r}")

