import json
import subprocess

CWD = "/Users/gabe/Projects/wisp-plugins/.claude/worktrees/review-slop-evaluation"
REPO = "/Users/gabe/Projects/caliper"


def run(cmd, cwd=CWD):
    p = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    return p.returncode, p.stdout.strip(), p.stderr.strip()


def g(*a):
    return run(["/usr/bin/git", "-C", REPO] + list(a))[1]


for n in (132, 142):
    print(f"\n################ caliper/{n}")
    rc, out, err = run(["entire", "trail", "show", f"caliper/{n}", "--project", "gh/orin-dx", "--json"])
    branch = None
    if rc == 0:
        d = json.loads(out)
        print("trail:", d.get("number"), d.get("title"))
        print("body:", (d.get("body") or "")[:700].replace("\n", " "))
        for c in d.get("changes", []):
            if c.get("repository") == "caliper" and c["number"] == n:
                branch = c.get("branch")
                print("branch:", branch, c.get("status"), c.get("title"))
    else:
        print("show ERR", err[-200:])
    if branch:
        rc, out, err = run(["gh", "pr", "list", "--repo", "orin-dx/caliper", "--head", branch, "--state", "all", "--json",
                            "number,state,mergeable,mergeStateStatus,reviewDecision,title,url"])
        print("PR:", out or err[-200:])
    for st in ("open", "resolved", "dismissed"):
        rc, out, err = run(["entire", "trail", "finding", "list", f"caliper/{n}", "--project", "gh/orin-dx", "--freshness", "any", "--status", st, "--json"])
        fs = json.loads(out)["findings"] if rc == 0 else []
        print(f"-- findings {st}: {len(fs)}")
        if st == "open":
            for x in fs:
                loc = x.get("location") or {}
                print(f"  {x['id'][-8:]} {x['severity']} conf={x.get('confidence')} {loc.get('filePath')} {x['createdAt'][:16]}")
                print("     ", x["body"][:1000].replace("\n", " "))
    if branch:
        ref = f"origin/{branch}"
        if g("rev-parse", "--verify", "--quiet", ref):
            base = g("merge-base", "origin/main", ref)
            print("ahead/behind main:", g("rev-list", "--left-right", "--count", f"origin/main...{ref}"))
            print(g("log", "--format=%h %G? %s", f"{base}..{ref}"))
            print(g("diff", "--stat", f"{base}..{ref}")[-1800:])
        else:
            print("branch not on remote (merged/deleted?)")

