"""Harvest all Entire trail findings (open/resolved/dismissed) for caliper, callisto, monokl."""
import json
import os
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor

CWD = "/Users/gabe/Projects/wisp-plugins/.claude/worktrees/review-slop-evaluation"
OUT = "/Users/gabe/.claude/jobs/45cd44b5/tmp/harvest3"
PROJECT = "gh/orin-dx"
REPOS = ["caliper", "callisto", "monokl"]
os.makedirs(OUT, exist_ok=True)
LOG = open(f"{OUT}/log.txt", "a")


def log(m):
    LOG.write(m + "\n")
    LOG.flush()


def run(args, retries=3):
    err = ""
    for _ in range(retries):
        p = subprocess.run(["entire"] + args, cwd=CWD, capture_output=True, text=True, timeout=300)
        if p.returncode == 0:
            return p.stdout, ""
        err = p.stderr.strip()[-300:]
        if "invalid" in err.lower() or "not found" in err.lower():
            break
    return None, err


def list_trails(repo):
    seen = {}
    for status in ["open", "closed"]:
        token = None
        while True:
            args = ["trail", "list", "--project", PROJECT, "--repo", f"{PROJECT}/{repo}", "--status", status,
                    "--limit", "100", "--json"]
            if token:
                args += ["--page-token", token]
            out, err = run(args)
            if out is None:
                log(f"trail list {repo} {status}: {err}")
                break
            d = json.loads(out)
            for it in d.get("items", []):
                seen[it["number"]] = it
            token = d.get("nextPageToken")
            log(f"{repo} {status}: +{len(d.get('items', []))} total={len(seen)} next={bool(token)}")
            if not token:
                break
    return seen


def trail_changes(item):
    repo, num = item
    out, err = run(["trail", "show", str(num), "--project", PROJECT, "--repo", f"{PROJECT}/{repo}", "--json"])
    if out is None:
        log(f"show {repo} {num}: {err}")
        return []
    d = json.loads(out)
    return [(repo, ch.get("repository", repo), ch["number"], num, d.get("title", ""), ch.get("branch", ""))
            for ch in d.get("changes", [])]


def pull_findings(ch):
    repo, rname, n, trail, title, branch = ch
    res = {"repo": repo, "change": f"{rname}/{n}", "trail": trail, "trail_title": title, "branch": branch, "by_status": {}}
    for st in ["open", "resolved", "dismissed"]:
        out, err = run(["trail", "finding", "list", f"{rname}/{n}", "--project", PROJECT, "--freshness", "any",
                        "--status", st, "--json"])
        if out is None:
            res["by_status"][st] = {"error": err}
            log(f"finding {rname}/{n} {st}: {err}")
        else:
            res["by_status"][st] = json.loads(out).get("findings", [])
    return res


def main():
    trails = {}
    for r in REPOS:
        trails[r] = list_trails(r)
    with ThreadPoolExecutor(4) as ex:
        chs = [c for lst in ex.map(trail_changes, [(r, n) for r in REPOS for n in sorted(trails[r])]) for c in lst]
    chs = sorted(set(chs))
    log(f"changes total {len(chs)}")
