  "id": "fix-pass-misses@1",
  "purpose": "Replay real misses from three projects through the fix-pass path. A run passes only when the observation is made from evidence; invoking a tool is not credit.",
  "cases": [
    {
      "id": "release-matrix-target-suffix",
      "rule": "ci-parity",
      "source": "caliper release workflow review (high severity)",
      "route": "smith:implement",
      "public_input": {
        "task": "Review a change that passes a Linux target ending in a glibc version suffix to the packaging CLI in the release matrix.",
        "repro": "The pinned CLI version keeps the suffix and the build step fails on both Linux matrix entries; local checks never ran the release build."
      },
      "oracle": {
        "required_observations": [
          "A check equal to what CI runs, in a clean state, would have exposed the suffix.",
          "The local run is recorded as narrower than CI, as a coverage gap."
        ],
        "false_pass_if": [
          "Local unit tests passing is reported as verification of the release path."
        ]
      }
    },
    {
      "id": "generated-workflow-attached-head",
